{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "mechanism",
      "statement": "When no appropriate index is available, an ORDER BY query gathers the output and runs it through a sorter, which can require substantial temporary storage.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_2",
      "facet": "mechanism",
      "statement": "If an index is available on the ORDER BY column, SQLite can scan that index and perform rowid lookups instead of sorting.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_3",
      "facet": "property",
      "statement": "Both the index scan (with rowid lookups) and the indexless sort can require work proportional to N log N.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_4",
      "facet": "mechanism",
      "statement": "SQLite uses a cost-based query planner that estimates the total time for each plan to choose between indexed and indexless sorts.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_5",
      "facet": "precondition",
      "statement": "The choice between index scan and sort can depend on table size and WHERE-clause constraints.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_6",
      "facet": "property",
      "statement": "The indexed sort generally uses less temporary storage because it does not accumulate the entire result before sorting.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_7",
      "facet": "mechanism",
      "statement": "A covering index can avoid the rowid lookups and reduce the cost further.",
      "start_line": 5,
      "end_line": 5
    }
  ],
  "claims": [],
  "questions": []
}
